    val x = sc.nextInt()
    val n = sc.nextLong()

    val primes = ArrayList<Int>()

    fun isPrime(k: Int): Boolean {
        if (k == 1) return false
        if (k == 2 || k == 3) return true
        for (i in 2..sqrt(k.toDouble()).toInt()) {
            if (k % i == 0) {
                return false
            }
        }
        return true

    }

    for (i in 2..sqrt(x.toDouble()).toInt()) {
        if (x % i == 0) {
            if (isPrime(i) && !primes.contains(x / i))
                primes += i
            if (isPrime(x / i) && !primes.contains(x / i))
                primes += x / i
        }
    }
    if (isPrime(x)) primes += x

    //primes.forEach { println(it) }

    val mod = 1000000007
    fun power(x: Long, p: Long): Long = when {
        p == 0L -> 1
        p == 1L -> x % mod
        p % 2 == 0L -> {
            val cur = power(x, p / 2)
            (cur * cur) % mod
        }
        else -> (power(x, p - 1) * x) % mod
    }

    var ans = 1L

    for (p in primes) {
        var curP = p.toLong()
        while (n / curP > 0) {
            //println(curP)
            ans = (ans * power(p.toLong(), n / curP)) % mod
            if ((curP * p) / p != curP) break
            curP *= p
        }
    }

    println(ans)
}

class Scanner(s: InputStream) {
    var st: StringTokenizer? = null
    val br: BufferedReader = BufferedReader(InputStreamReader(s))

    operator fun next(): String {
        while (st == null || !st!!.hasMoreTokens())
            st = StringTokenizer(br.readLine())
        return st!!.nextToken()
    }

    fun nextInt(): Int {
        return Integer.parseInt(next())
    }

    fun nextLong(): Long {
        return java.lang.Long.parseLong(next())
    }

    fun nextLine(): String {
        return br.readLine()
    }

    fun nextDouble(): Double {
        return java.lang.Double.parseDouble(next())
    }

    companion object {
        val sysIn = Scanner(System.`in`)
    }

}

val rnd = Random()
fun IntArray.sort() {
    val n = this.size
    for (i in 0 until n - 1) {
        val randomPos = i + rnd.nextInt(n - i - 1) + 1
        this[i] = this[i] xor this[randomPos]
        this[randomPos] = this[randomPos] xor this[i]
        this[i] = this[i] xor this[randomPos]
    }
    Arrays.sort(this)
}

fun LongArray.sort() {
    val n = this.size
    for (i in 0 until n - 1) {
        val randomPos = i + rnd.nextInt(n - i - 1) + 1
        this[i] = this[i] xor this[randomPos]
        this[randomPos] = this[randomPos] xor this[i]
        this[i] = this[i] xor this[randomPos]
    }
    Arrays.sort(this)
}
